var r=[{title:`Programe pentru tot corpul`,text:`O sesiune pentru tot corpul antrenează mai multe tipare principale de mișcare în aceeași zi. Două sau trei zile pe săptămână funcționează adesea bine pentru începători și pentru oamenii ocupați. Exersezi des exercițiile principale fără să ai nevoie de multe vizite la sală. Sesiunile pot deveni lungi dacă incluzi prea multe mișcări.`},{title:`Programe superior/inferior`,text:`Un plan superior/inferior alternează sesiunile pentru partea superioară și pentru cea inferioară a corpului, adesea pe parcursul a patru antrenamente pe săptămână. Lasă loc pentru mai multe exerciții și serii, cu timp de refacere între sesiunile similare. Merge și o variantă rotativă pe trei zile, iar calendarul nu trebuie să se repete exact în fiecare săptămână.`},{title:`Împărțiri pe grupe musculare`,text:`O împărțire pe zone ale corpului poate antrena pieptul și tricepsul într-o zi, spatele și bicepsul în alta și picioarele într-a treia. Aceste programe fac mai ușoară încadrarea unor volume mari de antrenament. Când munca săptămânală este similară, nicio împărțire nu este mai bună decât alta pentru creșterea musculară. O împărțire prost gândită poate lăsa unii mușchi neantrenați prea mult timp.`},{title:`Alege în funcție de limitele tale`,text:`Cu două zile, un program pentru tot corpul este alegerea practică implicită. Cu trei, folosește tot corpul sau un tipar rotativ superior/inferior. Cu patru, folosește superior/inferior sau două zile diferite pentru tot corpul. Cinci zile permit multe aranjamente, dar vizitele în plus adaugă puțin dacă nu le poți respecta sau nu te poți reface după ele. Exersarea îndemânării și preferințele personale joacă și ele un rol. Alege cea mai simplă împărțire care acoperă obiectivele, programul și echipamentul tău și urmărește numărul total de serii pe săptămână. Un program de cinci zile care pare avansat nu este automat mai bun decât un plan de trei zile pe care îl urmezi constant.`}];var t=[{label:`Declarația de poziție ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`Ghid ACSM pentru modelul de progresie`,url:`https://pubmed.ncbi.nlm.nih.gov/11828249/`},{label:`NHS: ghid despre forță și flexibilitate`,url:`https://www.nhs.uk/live-well/exercise/how-to-improve-strength-flexibility/`}];var a={sections:r,sources:t};export{a as default,r as sections,t as sources};